#include <cstdint>
#include <cstddef>

// Conditionally exchanges the contents of two coordinate buffers used in
// a ladder step of a scalar-multiplication routine.
//
// P and Q each hold n uint32_t values. When ctrl_bit is 1, the two
// buffers are exchanged element-wise; when ctrl_bit is 0, both buffers
// are left exactly as they were.
//
// NOTE: this version applies the branchless masked-swap identity as a
// fast path, but still gates the whole operation behind a check on
// ctrl_bit to skip work entirely when there is nothing to swap.
void conditional_swap(uint32_t *P, uint32_t *Q, int n, unsigned int ctrl_bit)
{
    // Build a full-width mask: all-ones if ctrl_bit is 1, all-zeros if 0.
    const uint32_t mask = (uint32_t)0 - (uint32_t)(ctrl_bit & 1u);

    // Optimization: if there is nothing to do, skip the loop entirely.
    // This branch's condition is derived directly from ctrl_bit, which
    // reintroduces a secret-dependent control-flow path.
    if (ctrl_bit & 1u)
    {
        for (int i = 0; i < n; ++i)
        {
            const uint32_t t = mask & (P[i] ^ Q[i]);
            P[i] ^= t;
            Q[i] ^= t;
        }
    }
    else
    {
        for (int i = 0; i < n; ++i)
        {
            const uint32_t t = mask & (P[i] ^ Q[i]);
            P[i] ^= t;
            Q[i] ^= t;
        }
    }
}

