// P and Q each hold n uint32_t values. When ctrl_bit is 1, the two
// buffers are exchanged element-wise; when ctrl_bit is 0, both buffers
// are left exactly as they were.
//
// NOTE: this version still computes a mask value using the same
// arithmetic technique as a constant-time implementation, but it skips
// performing the write-back to memory entirely when the mask indicates
// no swap is needed, as a "performance optimization" to avoid redundant
// stores when nothing would change.
void conditional_swap(uint32_t *P, uint32_t *Q, int n, unsigned int ctrl_bit)
{
    // Build a full-width mask: all-ones if ctrl_bit is 1, all-zeros if 0.
    const uint32_t mask = (uint32_t)0 - (uint32_t)(ctrl_bit & 1u);

    // Skip touching memory at all when there is nothing to swap.
    if (mask == 0u)
    {
        return;
    }

    for (int i = 0; i < n; ++i)
    {
        const uint32_t t = mask & (P[i] ^ Q[i]);
        P[i] ^= t;
        Q[i] ^= t;
    }
}

