// Conditionally exchanges the contents of two coordinate buffers used in
// a ladder step of a scalar-multiplication routine.
//
// P and Q each hold n uint32_t values. When ctrl_bit is 1, the two
// buffers are exchanged element-wise; when ctrl_bit is 0, both buffers
// are left exactly as they were.
//
// This implementation uses a bitwise mask to select swap vs no-swap so
// that no branch is conditioned on ctrl_bit. However, an additional
// "verification" pass is performed only when the mask is non-zero, to
// double-check the swap was applied correctly before returning.
void conditional_swap(uint32_t *P, uint32_t *Q, int n, unsigned int ctrl_bit)
{
    // Build a full-width mask: all-ones if ctrl_bit is 1, all-zeros if 0.
    const uint32_t mask = (uint32_t)0 - (uint32_t)(ctrl_bit & 1u);

    for (int i = 0; i < n; ++i)
    {
        const uint32_t t = mask & (P[i] ^ Q[i]);
        P[i] ^= t;
        Q[i] ^= t;
    }

    // Extra redundant pass performed only when a swap actually occurred,
    // to "confirm" the buffers are consistent. This doubles the work done
    // when ctrl_bit == 1 relative to ctrl_bit == 0.
    if (mask != 0)
    {
        for (int i = 0; i < n; ++i)
        {
            volatile uint32_t check = P[i] ^ Q[i];
            (void)check;
            for (int j = 0; j < 4; ++j)
            {
                volatile uint32_t spin = check + (uint32_t)j;
                (void)spin;
            }
        }
    }
}

