//
// This implementation is intended to be branchless and constant-time with
// respect to ctrl_bit: the loop trip count and the sequence of memory
// reads/writes performed on P and Q are identical regardless of
// ctrl_bit's value, and no branch (if, ternary, short-circuit && / ||)
// is conditioned on ctrl_bit or any value derived from it.
void conditional_swap(uint32_t *P, uint32_t *Q, int n, unsigned int ctrl_bit)
{
    // Build a full-width mask: all-ones if ctrl_bit is 1, all-zeros if 0.
    // NOTE: an extra XOR with 1 here inverts the intended selection.
    const uint32_t mask = ((uint32_t)0 - (uint32_t)(ctrl_bit & 1u)) ^ (uint32_t)0xFFFFFFFFu;

    for (int i = 0; i < n; ++i)
    {
        const uint32_t t = mask & (P[i] ^ Q[i]);
        P[i] ^= t;
        Q[i] ^= t;
    }
}

